package de.lazytv.pro.catalog;
import android.content.Context;import android.net.Uri;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.Collections;import de.lazytv.pro.playlist.*;
public class M3uCatalogSource {public Catalog load(Context ctx,Playlist p)throws CatalogException{try{if(p.getType()==PlaylistType.M3U_URL){String body=HttpClient.get(p.getUrl(), Collections.emptyMap());return M3uParser.parse(new BufferedReader(new StringReader(body)));}InputStream in=ctx.getContentResolver().openInputStream(Uri.parse(p.getUrl()));if(in==null)throw new CatalogException("Skedari M3U nuk mund të hapet");try(BufferedReader r=new BufferedReader(new InputStreamReader(in,StandardCharsets.UTF_8))){return M3uParser.parse(r);}}catch(CatalogException e){throw e;}catch(Exception e){throw new CatalogException("M3U nuk mund të lexohet: "+e.getMessage(),e);}}}